def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]

    # Find the direction in which the visible color bands are constant.
    axes = [
        ("row", lambda r, c: r),
        ("col", lambda r, c: c),
        ("diag", lambda r, c: c-r),
        ("anti", lambda r, c: r+c),
    ]
    choices = []
    for name, coord in axes:
        groups = {}
        valid = True
        for r, c, color in cells:
            k = coord(r, c)
            if k in groups and groups[k] != color:
                valid = False
                break
            groups[k] = color
        if valid:
            # Prefer an orientation supported by multiple cells on the same bands.
            counts = {}
            for r, c, color in cells:
                k = coord(r, c)
                counts[k] = counts.get(k, 0) + 1
            support = sum(n*(n-1)//2 for n in counts.values())
            choices.append((support, len(groups), name, coord, groups))
    if not choices:
        return [row[:] for row in grid]
    _, _, _, coord, observed = max(choices, key=lambda x: (x[0], x[1]))

    positions = [coord(r, c) for r, c, _ in cells]
    span = max(positions) - min(positions) + 1
    period = span
    phase_colors = {}
    for p in range(1, span + 1):
        trial = {}
        ok = True
        for k, color in observed.items():
            phase = k % p
            if phase in trial and trial[phase] != color:
                ok = False
                break
            trial[phase] = color
        if ok:
            period, phase_colors = p, trial
            break

    # All phases are usually anchored by examples; fill any remaining phase
    # from the nearest known phase if the evidence is sparse.
    for phase in range(period):
        if phase not in phase_colors:
            nearest = min(phase_colors, key=lambda q: min((phase-q) % period, (q-phase) % period))
            phase_colors[phase] = phase_colors[nearest]
    return [[phase_colors[coord(r, c) % period] for c in range(w)] for r in range(h)]
